 */
import React from "react";

export function Targeta() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Balance Card Component</title>


    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
    <style>
        body {
            font-family: 'Inter', sans-serif;
        }

        .chart-container {
            position: relative;
            height: 200px;
            width: 100%;
        }

        /* Efecto de luz que sigue al mouse */
        #chart-glow {
            position: absolute;
            bottom: 0;
            width: 100px;
            height: 120px;
            background: radial-gradient(ellipse at bottom, rgba(168, 85, 247, 0.6) 0%, rgba(168, 85, 247, 0.3) 30%, transparent 70%);
            opacity: 0;
            transition: opacity 0.2s ease, left 0.1s ease;
            transform: translateX(-50%);
            pointer-events: none;
            z-index: 0;
            filter: blur(20px);
        }

        /* Switch mejorado */
        .switch-container {
            position: relative;
            background: rgba(63, 63, 70, 0.4);
            border-radius: 9999px;
            padding: 3px;
            width: 72px;
            height: 36px;
            cursor: pointer;
            border: 1px solid rgba(113, 113, 122, 0.3);
        }

        .switch-thumb {
            position: absolute;
            top: 3px;
            left: 3px;
            width: 30px;
            height: 30px;
            background: linear-gradient(135deg, #a855f7, #8b5cf6);
            border-radius: 9999px;
            transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            box-shadow: 0 0 20px rgba(168, 85, 247, 0.5),
                        0 2px 8px rgba(0, 0, 0, 0.3);
        }

        .switch-container.active .switch-thumb {
            transform: translateX(36px);
        }

        .switch-icon {
            position: relative;
            z-index: 10;
            width: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #71717a;
            transition: color 0.3s ease;
        }

        .switch-container:not(.active) .switch-icon:first-child,
        .switch-container.active .switch-icon:last-child {
            color: #ffffff;
        }

        /* Pestañas de tiempo */
        .time-tab {
            transition: all 0.3s ease;
            color: #71717a;
        }

        .time-tab.active {
            background: linear-gradient(135deg, #8b5cf6, #a855f7);
            color: #ffffff;
            box-shadow: 0 4px 12px rgba(139, 92, 246, 0.4);
        }

        .time-tab:not(.active):hover {
            color: #c084fc;
        }

        /* Animación de transición del gráfico */
        .chart-transitioning {
            opacity: 0.5;
            transform: scale(0.98);
        }

        #balanceChart {
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }
    </style>
</head>
<body class="bg-zinc-950 flex items-center justify-center min-h-screen p-4">

    <div class="w-full max-w-md rounded-3xl p-6 bg-zinc-900/90 backdrop-blur-xl border border-zinc-800 shadow-2xl">
        <div class="flex flex-col space-y-6">

            <!-- Cabecera -->
            <div class="flex justify-between items-start">
                <div class="space-y-1">
                    <p class="text-sm text-zinc-500 font-medium">Total balance</p>
                    <div class="flex items-baseline space-x-3">
                        <p class="text-4xl font-bold text-white">$11,920</p>
                        <div class="flex items-center text-sm font-semibold text-emerald-400">
                            <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.5">
                                <path stroke-linecap="round" stroke-linejoin="round" d="M5 10l7-7m0 0l7 7m-7-7v18" />
                            </svg>
                            <span>14.2%</span>
                        </div>
                    </div>
                </div>

                <!-- Switch mejorado -->
                <div id="chart-switch" class="switch-container">
                    <div class="switch-thumb"></div>
                    <div class="flex h-full">
                        <button class="switch-icon">
                            <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                                <path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zM8 7a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zM14 4a1 1 0 011-1h2a1 1 0 011 1v12a1 1 0 01-1 1h-2a1 1 0 01-1-1V4z"/>
                            </svg>
                        </button>
                        <button class="switch-icon">
                            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 3.055A9.001 9.001 0 1020.945 13H11V3.055z"/>
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20.488 9H15V3.512A9.025 9.025 0 0120.488 9z"/>
                            </svg>
                        </button>
                    </div>
                </div>
            </div>

            <!-- Gráfico -->
            <div class="chart-container">
                <div id="chart-glow"></div>
                <canvas id="balanceChart"></canvas>
            </div>

            <!-- Pestañas de tiempo -->
            <div id="time-tabs" class="flex justify-between items-center bg-zinc-800/50 rounded-full p-1.5 border border-zinc-700/50">
                <button data-time="1W" class="time-tab font-semibold py-2.5 px-4 rounded-full text-sm transition-all">1W</button>
                <button data-time="1M" class="time-tab active font-semibold py-2.5 px-4 rounded-full text-sm transition-all">1M</button>
                <button data-time="6M" class="time-tab font-semibold py-2.5 px-4 rounded-full text-sm transition-all">6M</button>
                <button data-time="1Y" class="time-tab font-semibold py-2.5 px-4 rounded-full text-sm transition-all">1Y</button>
                <button data-time="ALL" class="time-tab font-semibold py-2.5 px-4 rounded-full text-sm transition-all">ALL</button>
            </div>

        </div>
    </div>



</body>
</html>" }} />
  );
}
